mapper.select:
SELECT * FROM (
    SELECT  FROM DOC_REGISTRY
     WHERE REG_YEAR = #{year}
       AND (DEPT_NAME = #{dept} OR HANDLER_ID = #{loginId} OR REGISTERED_BY = #{loginId})
       AND REG_TYPE = #{type}
       AND (TITLE LIKE '%' || #{q} || '%' OR REG_NO LIKE '%' || #{q} || '%'
                                 OR COUNTERPART LIKE '%' || #{q} || '%')
     ORDER BY REG_DATE DESC, REG_ID DESC
) WHERE ROWNUM <= #{limit}
